// Native chrome colours for Expo prebuild (splash screen, status bar, Android colorPrimary) come from the SpaceUI
// dark scheme roles generated by scripts/m3-roles.ts, which also keeps the committed android/ and ios/ resources
// on the same values. app.json carries the rest of the static config.
import type { ConfigContext, ExpoConfig } from "expo/config";
import roles from "./src/theme/m3-roles.json";

const { primary, surface } = roles.dark;

export default ({ config }: ConfigContext): ExpoConfig =>
	({
		...config,
		primaryColor: primary,
		backgroundColor: surface,
		androidStatusBar: { backgroundColor: surface, barStyle: "light-content" },
		plugins: [...(config.plugins ?? []), ["expo-splash-screen", { backgroundColor: surface }]],
	}) as ExpoConfig;
